close({
	version:   "1.0" | "1.1" | *"1.2"
	namespace: string & =~"^[-_,A-Za-z0-9]+$" | *"default"
	flags: [...{_version: version} & #Flag]
	segments: [...#Segment]
})

#Flag: {
	_version:     string
	key:          string & =~"^[-_,A-Za-z0-9]+$"
	name:         string & =~"^.+$"
	description?: string
	enabled:      bool | *false
	variants: [...#Variant]
	rules: [...#Rule]
	if _version == "1.1" || _version == "1.2" {
		type: "BOOLEAN_FLAG_TYPE" | *"VARIANT_FLAG_TYPE"
		#FlagBoolean | *{}
	}
}

#FlagBoolean: {
	type: "BOOLEAN_FLAG_TYPE"
	rollouts: [...{
		description?: string
		#Rollout
	}]
}

#Variant: {
	key:          string & =~"^.+$"
	name:         string & =~"^.+$"
	description?: string
	attachment:   {...} | *null
}

#RuleSegment: {
	keys: [...string]
	operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
}

#Rule: {
	segment: string & =~"^[-_,A-Za-z0-9]+$" | #RuleSegment
	rank?:   int
	distributions: [...#Distribution]
}

#Distribution: {
	variant: string & =~"^.+$"
	rollout: >=0 & <=100
}

#RolloutSegment: {key: string & =~"^[-_,A-Za-z0-9]+$"} | {keys: [...string]}

#Rollout: {
	segment: {
		#RolloutSegment
		operator: "OR_SEGMENT_OPERATOR" | "AND_SEGMENT_OPERATOR" | *null
		value:    bool
	}
} | {
	threshold: {
		percentage: float
		value:      bool
	}
	// failure to add the following causes it not to close
} | *{} // I found a comment somewhere that this helps with distinguishing disjunctions

#Segment: {
	key:          string & =~"^[-_,A-Za-z0-9]+$"
	name:         string & =~"^.+$"
	match_type:   "ANY_MATCH_TYPE" | "ALL_MATCH_TYPE"
	description?: string
	constraints: [...#Constraint]
}

#Constraint: ({
	type:         "STRING_COMPARISON_TYPE"
	property:     string & =~"^.+$"
	value?:       string
	description?: string
	operator:     "eq" | "neq" | "empty" | "notempty" | "prefix" | "suffix"
} | {
	type:         "NUMBER_COMPARISON_TYPE"
	property:     string & =~"^.+$"
	value?:       string
	description?: string
	operator:     "eq" | "neq" | "present" | "notpresent" | "le" | "lte" | "gt" | "gte"
} | {
	type:         "BOOLEAN_COMPARISON_TYPE"
	property:     string & =~"^.+$"
	value?:       string
	operator:     "true" | "false" | "present" | "notpresent"
	description?: string
} | {
	type:         "DATETIME_COMPARISON_TYPE"
	property:     string & =~"^.+$"
	value?:       string
	description?: string
	operator:     "eq" | "neq" | "present" | "notpresent" | "le" | "lte" | "gt" | "gte"
})

package fs

import (
	"context"
	"fmt"
	"io/fs"
	"path"

	"go.uber.org/zap"
)

// FSSource produces implementations of fs.FS.
// A single FS can be produced via Get or a channel
// may be provided to Subscribe in order to received
// new instances when new state becomes available.
type FSSource interface {
	fmt.Stringer

	// Get builds a single instance of an fs.FS
	Get() (fs.FS, error)

	// Subscribe feeds implementations of fs.FS onto the provided channel.
	// It should block until the provided context is cancelled (it will be called in a goroutine).
	// It should close the provided channel before it returns.
	Subscribe(context.Context, chan<- fs.FS)
}

// Store is an implementation of storage.Store backed by an FSSource.
// The store subscribes to the source for instances of fs.FS with new contents.
// When a new fs is received the contents is fetched and built into a snapshot
// of Flipt feature flag state.
type Store struct {
	*syncedStore

	logger *zap.Logger
	source FSSource

	// notify is used for test purposes
	// it is invoked if defined when a snapshot update finishes
	notify func()

	cancel context.CancelFunc
	done   chan struct{}
}

func (l *Store) updateSnapshot(fs fs.FS) error {
	storeSnapshot, err := snapshotFromFS(l.logger, fs)
	if err != nil {
		return err
	}

	l.mu.Lock()
	l.storeSnapshot = storeSnapshot
	l.mu.Unlock()

	// NOTE: this is really just a trick for unit tests
	// It is used to signal that an update occurred
	// so we dont have to e.g. sleep to know when
	// to check state.
	if l.notify != nil {
		l.notify()
	}

	return nil
}

// NewStore constructs and configure a Store.
// The store creates a background goroutine which feeds a channel of fs.FS.
func NewStore(logger *zap.Logger, source FSSource) (*Store, error) {
	store := &Store{
		syncedStore: &syncedStore{},
		logger:      logger,
		source:      source,
		done:        make(chan struct{}),
	}

	// get an initial FS from source.
	f, err := source.Get()
	if err != nil {
		return nil, err
	}

	if err := store.updateSnapshot(f); err != nil {
		return nil, err
	}

	var ctx context.Context
	ctx, store.cancel = context.WithCancel(context.Background())

	ch := make(chan fs.FS)
	go source.Subscribe(ctx, ch)

	go func() {
		defer close(store.done)
		for fs := range ch {
			logger.Debug("received new fs")

			if err = store.updateSnapshot(fs); err != nil {
				logger.Error("failed updating snapshot", zap.Error(err))
				continue
			}

			logger.Debug("updated latest fs")
		}

		logger.Info("source subscription closed")
	}()

	return store, nil
}

